package com.auraboot.framework.plugin.extension;

import java.io.InputStream;
import java.util.List;

/**
 * Host-provided file byte bridge for plugin command handlers.
 *
 * <p>Plugins receive this accessor through
 * {@link CommandHandlerExtension.CommandContext#fileAccessor()}. It keeps
 * platform storage details inside the host while allowing plugins to read
 * uploaded files and persist generated files by platform file id.</p>
 */
public interface FileAccessor {

    /** Well-known key for FileAccessor in the command settings map. */
    String SETTINGS_KEY = "__fileAccessor";

    /**
     * Open a platform file by its public file id.
     *
     * @param fileId platform file pid/id returned by the upload API
     * @return readable file stream; caller must close it
     */
    InputStream open(String fileId);

    /**
     * Describe a tenant-visible file by its stable public pid.
     *
     * <p>The default keeps older host implementations binary-compatible while
     * allowing security-sensitive handlers to fail closed when metadata is not
     * available. Implementations must not accept storage keys or internal
     * numeric ids through this method.</p>
     *
     * @param fileId stable public file pid returned by the upload API
     * @return tenant-scoped metadata, or {@code null} when the host does not
     *         implement the metadata capability
     */
    default FileMetadata describe(String fileId) {
        return null;
    }

    /**
     * Whether a tenant-visible public file pid is linked to a business object
     * field through the platform file-relation registry.
     *
     * <p>The conservative default is {@code false}; callers must never infer a
     * relationship merely because {@link #open(String)} succeeds.</p>
     */
    default boolean isLinkedTo(String fileId, String entityType, String entityId, String fieldName) {
        return false;
    }

    /**
     * Apply a monotonic retention lock to released/auditable file bytes.
     *
     * <p>The conservative default keeps older hosts binary compatible while making
     * security-sensitive release handlers fail closed when retention is unavailable.</p>
     */
    default boolean retain(String fileId) {
        return false;
    }

    /**
     * Persist generated bytes as a platform file.
     *
     * @param originalName suggested download filename
     * @param contentType  MIME type
     * @param bytes        file content
     * @return saved platform file metadata
     */
    SavedFile save(String originalName, String contentType, byte[] bytes);

    /**
     * Persist generated bytes and establish the business-object relation used by
     * the host download authorizer. Security-sensitive exports must use this method instead
     * of assuming that storing a public file pid in a dynamic field creates a file relation.
     *
     * <p>The conservative default fails closed so plugins cannot silently publish an unlinked
     * artifact when running on an older host.</p>
     */
    default SavedFile saveAndLink(
            String originalName,
            String contentType,
            byte[] bytes,
            String entityType,
            String entityId,
            String fieldName
    ) {
        throw new UnsupportedOperationException("generated file relation capability is unavailable");
    }

    /**
     * Persist bytes and append their relation without replacing existing attachments.
     * Older hosts fail closed rather than silently detaching previously signed files.
     */
    default SavedFile saveAndAppendLink(String originalName, String contentType, byte[] bytes,
                                       String entityType, String entityId, String fieldName) {
        throw new UnsupportedOperationException("append file relation capability is unavailable");
    }

    /** List tenant-visible files linked to one business object field. */
    default List<FileMetadata> listLinked(String entityType, String entityId, String fieldName) {
        throw new UnsupportedOperationException("linked file listing capability is unavailable");
    }

    default boolean delete(String fileId, String actorUserId) {
        throw new UnsupportedOperationException("file deletion capability is unavailable");
    }

    /**
     * Link an existing uploaded file to an authorized business record without copying bytes.
     * Hosts must validate the public file identity and ownership before creating a relation.
     * A field key identifies one attachment slot; callers retaining versions must use distinct keys.
     */
    default void linkExisting(String fileId, String entityType, String entityId, String fieldName) {
        throw new UnsupportedOperationException("uploaded file relation capability is unavailable");
    }

    /**
     * Complete a single-file association for an exact record successfully created through this
     * command's DataAccessor in the same physical transaction. The scalar file field must already
     * contain this PID. This never replaces a relation or grants UPDATE access to an immutable row.
     * Older/unscoped hosts fail closed. Bulk create and historical/non-owner evidence are not implied.
     */
    default void linkAndRetainExistingToCreatedRecord(String filePid, String modelCode, String recordPid, String fieldCode) {
        throw new UnsupportedOperationException("Command-created record attachment linking is not supported");
    }

    /**
     * Append an owned finalized upload to the original human command's root record and retain
     * its bytes, atomically in the caller's physical Core transaction. Existing relations remain.
     * The host validates the published multi-file field and its exact command writer. The caller
     * must perform its parent CAS/projection first in the same transaction; this method does not
     * update the business field, create a child relation, or copy bytes. Repeated exact links are
     * idempotent. Append distinct file PIDs in ascending order to prevent cross-root lock cycles.
     * Nested commands cannot install this capability. The capability expires when the handler returns and rejects async use, another
     * thread, identity/target changes and a suspended/replaced transaction (including REQUIRES_NEW).
     * A failure must abort the original command transaction.
     *
     * @param filePid exact public PID of an active finalized upload owned by the current user
     * @param fieldCode real published root multi-file field code
     */
    default void appendAndRetainExistingToTarget(String filePid, String fieldCode) {
        throw new UnsupportedOperationException("command target file append capability is unavailable");
    }

    /** Saved platform file metadata returned to plugin handlers. */
    record SavedFile(String fileId, String originalName, long size, String url) {
    }

    /** Tenant-scoped, storage-opaque metadata for an existing platform file. */
    record FileMetadata(
            String fileId,
            String originalName,
            long size,
            String contentType,
            String ownerUserId,
            String status
    ) {
    }
}
